param([Parameter(Mandatory=$true)][string]$PackageRoot,[string]$InstallRoot='C:\Program Files\{{SERVICE}}',[string]$DataRoot='C:\ProgramData\{{SERVICE}}',[string]$TaskName='{{SERVICE}} Service')
$ErrorActionPreference='Stop';$missing=@('msvcp140.dll','msvcp140_atomic_wait.dll','vcruntime140.dll','vcruntime140_1.dll','vcruntime140_threads.dll')|Where-Object {!(Test-Path (Join-Path $env:WINDIR "System32\$_"))};if($missing){throw "Microsoft Visual C++ 2015-2022 Redistributable (x64) is required. Install Microsoft's vc_redist.x64.exe before updating {{SERVICE}}. Missing: $($missing -join ', ')"}
$old=Get-Content -Raw "$InstallRoot\current.json"|ConvertFrom-Json;$manifest=Get-Content -Raw "$PackageRoot\package-manifest.json"|ConvertFrom-Json;foreach($entry in $manifest.files){$p=Join-Path $PackageRoot $entry.path;if((Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.sha256){throw "Package hash mismatch: $($entry.path)"}}
$release="$InstallRoot\releases\$($manifest.version)";New-Item -ItemType Directory -Force -Path "$release\application"|Out-Null;Copy-Item "$PackageRoot\payload\application\*" "$release\application" -Recurse -Force;Copy-Item "$PackageRoot\payload\python-runtime" "$release\python-runtime" -Recurse;Copy-Item "$PackageRoot\tools\*" "$InstallRoot\tools" -Force
$stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssZ');$backup="$DataRoot\backups\data-$stamp";Copy-Item "$DataRoot\data" $backup -Recurse;Stop-ScheduledTask $TaskName -ErrorAction SilentlyContinue;[ordered]@{version=$manifest.version;previous=$old.version}|ConvertTo-Json|Set-Content "$InstallRoot\current.json" -Encoding utf8
try{Start-ScheduledTask $TaskName;Start-Sleep 2;& "$InstallRoot\tools\Test-{{SERVICE}}Health.ps1" -DataRoot $DataRoot|Out-Null}catch{[ordered]@{version=$old.version;previous=$manifest.version}|ConvertTo-Json|Set-Content "$InstallRoot\current.json" -Encoding utf8;Start-ScheduledTask $TaskName;throw "Update rolled back: $($_.Exception.Message)"};[ordered]@{updated=$true;from=$old.version;to=$manifest.version;data_backup=$backup}|ConvertTo-Json
